mapper.update:
MERGE INTO T_CLASS_FINISH_QTY a USING (
SELECT #{finishQty.procedureCode,jdbcType=VARCHAR} PROCEDURE_CODE, #{finishQty.finishDate,jdbcType=DATE} SCHEDULE_DATE, #{finishQty.materialCode,jdbcType=DATE} MATERIAL_CODE, #{finishQty.class1FinishQty,jdbcType=DOUBLE} CLASS1_FINISH_QTY, #{finishQty.class2FinishQty,jdbcType=DOUBLE} CLASS2_FINISH_QTY, #{finishQty.class3FinishQty,jdbcType=DOUBLE} CLASS3_FINISH_QTY FROM dual
) b ON (a.SCHEDULE_DATE = b.SCHEDULE_DATE AND a.MATERIAL_CODE = b.MATERIAL_CODE AND a.PROCEDURE_CODE = b.PROCEDURE_CODE AND a.DEL_FLAG = '0') WHEN MATCHED THEN UPDATE SET a.CLASS1_FINISH_QTY = nvl(b.CLASS1_FINISH_QTY, a.CLASS1_FINISH_QTY), a.CLASS2_FINISH_QTY = nvl(b.CLASS2_FINISH_QTY, a.CLASS2_FINISH_QTY), a.CLASS3_FINISH_QTY = nvl(b.CLASS3_FINISH_QTY, a.CLASS3_FINISH_QTY), a.UPDATE_TIME = now() WHEN NOT MATCHED THEN INSERT (a.ID, a.PROCEDURE_CODE, a.SCHEDULE_DATE, a.MATERIAL_CODE, a.CLASS1_FINISH_QTY, a.CLASS2_FINISH_QTY, a.CLASS3_FINISH_QTY, a.CREATE_TIME, a.DEL_FLAG) VALUES (get_sequence_nextval('SEQ_CLASS_FINISH_QTY'), b.PROCEDURE_CODE, b.SCHEDULE_DATE, b.MATERIAL_CODE, b.CLASS1_FINISH_QTY, b.CLASS2_FINISH_QTY, b.CLASS3_FINISH_QTY, now(), '0')
